export interface Options {
  description?: string;
}
export interface Schema {
  kind: string;
  description?: string;
}
export interface TText extends Schema {
  kind: "Text";
  type: "string";
}
export interface TCount extends Schema {
  kind: "Count";
  type: "number";
}
export type Properties = Record<string, Schema>;
export interface TGroup<P extends Properties = Properties> extends Schema {
  kind: "Group";
  type: "object";
  properties: P;
  required: string[];
}
export declare function Text(options?: Options): TText;
export declare function Count(options?: Options): TCount;
export declare function Group<P extends Properties>(properties: P, options?: Options): TGroup<P>;
